style.css:
@-moz-document domain("app.getcoralai.com") {
/* General Background */
    body, .app-container, .dashboard-container {
        background-color: #ffffff !important;
        color: #333333 !important;
    }

    /* Navbar */
    .navbar, .topbar, .header {
        background-color: #5D7690 !important;
        color: #ffffff !important;
    }

    /* Navbar links */
    .navbar a, .topbar a, .header a {
        color: #ffffff !important;
    }
    .navbar a:hover, .topbar a:hover, .header a:hover {
        color: #dbe4ec !important;
    }

    /* Buttons */
    button, .btn, .chat-button, .upload-button {
        background-color: #5D7690 !important;
        color: #ffffff !important;
        border: none !important;
        padding: 10px 15px !important;
        border-radius: 5px !important;
    }
    button:hover, .btn:hover, .chat-button:hover, .upload-button:hover {
        background-color: #4b6076 !important;
    }

    /* Tables */
    table, .file-table {
        border: 1px solid #dbe4ec !important;
    }
    th {
        background-color: #5D7690 !important;
        color: #ffffff !important;
    }
    td {
        background-color: #f5f7fa !important;
        color: #333333 !important;
    }

    /* Inputs & Select Fields */
    input, textarea, select {
        background-color: #ffffff !important;
        color: #333333 !important;
        border: 1px solid #5D7690 !important;
        padding: 5px !important;
        border-radius: 4px !important;
    }
    input:focus, textarea:focus, select:focus {
        border-color: #4b6076 !important;
        outline: none !important;
    }

    /* Sidebar (if applicable) */
    .sidebar {
        background-color: #5D7690 !important;
        color: #ffffff !important;
    }

    /* Table Row Hover */
    tr:hover {
        background-color: #e6edf5 !important;
    }

    /* Miscellaneous */
    a {
        color: #5D7690 !important;
    }
    a:hover {
        color: #4b6076 !important;
    }
}
